// https://<host>/p/<slug>, optionally with a trailing slash, query or fragment. No userinfo or port.
const postSlug = (link, host) => {
  const m = /^https:\/\/([A-Za-z0-9.-]+)\/p\/([a-z0-9-]{1,200})\/?(?:[?#][^\s]*)?$/.exec(String(link).trim());
  return m && m[1].toLowerCase() === host ? m[2] : null;
};
const body = $json.body ?? {};
const store = body.store === undefined ? 'live' : String(body.store);
if (!/^(live|fixture-[a-z0-9-]{1,40})$/.test(store)) throw new Error('invalid-request: unknown store');
const host = 'saveusnow.substack.com';
if (!postSlug(String(body.url ?? ''), host)) throw new Error('wrong-publication: not a post URL on the allowed publication');
const out = { store, url: String(body.url), publicationHost: host };
// Test fixtures stand in for the network, and only for isolated fixture-* stores.
if (store.startsWith('fixture-')) {
  if (typeof body.fixturePost !== 'object' || body.fixturePost === null) throw new Error('invalid-request: fixture stores need fixturePost');
  out.fixturePost = body.fixturePost; out.fixtureTranscript = body.fixtureTranscript ?? null;
}
return [{ json: out }];
